using System.Text.Json;using VisionCore;using VisionFramework;using VisionPlugins.ImageBinary;
static class RegionRuntimeChecks{
 public static void Run(Action<bool,string> check){var plugin=new ImageBinaryPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value);void Put(string n,object v)=>values[n]=JsonSerializer.SerializeToElement(v);Put("LowThreshold",0);Put("HighThreshold",255);Put("OutputMaskImage",true);var image=new GrayImage(32,32,Enumerable.Repeat((byte)255,1024).ToArray());var inputs=new Dictionary<string,PortValue>{{"Image",PortValue.Image(image)}};var rect=new RoiDocument("r",RoiKind.Rectangle,8,8,8,8);ModuleResult Run()=>plugin.CreateRuntime().ExecuteAsync(new("b",".",inputs,values,[rect]),default).Result;Put("RoiSelect",1);Put("InheritWay",0);inputs["Region"]=PortValue.Region([rect]);var inherited=Run();check(inherited.Status==ModuleStatus.Success&&inherited.Outputs["ProcessedPixels"].As<long>()==64,"按矩形区域继承后实际处理64像素");inputs.Remove("Region");check(Run().Status==ModuleStatus.Failed,"继承源缺失不会回退到手工区域");Put("InheritWay",1);foreach(var p in new[]{("ROICenterX",8d),("ROICenterY",8d),("ROIWidth",8d),("ROIHeight",8d),("ROIAngle",0d)})Put(p.Item1,p.Item2);inputs["ROIWidth"]=PortValue.Number(4);check(Run().Outputs["ProcessedPixels"].As<long>()==32,"参数订阅覆盖数值并参与实际栅格计算");inputs.Remove("ROIWidth");Put("ExternRoiSelect",1);inputs["InputBlindRegion"]=PortValue.Region([new("p",RoiKind.Polygon,0,0,Vertices:[new(4,4),new(8,4),new(8,12),new(4,12)])]);check(Run().Outputs["ProcessedPixels"].As<long>()<64,"继承多边形参与真实屏蔽计算");Put("ExternRoiSelect",0);Put("Assist0",true);Put("SelectWay",0);inputs["CorrectInfo"]=PortValue.Fixture(new(new(),new(8,4)));var moved=Run();var mask=moved.Outputs["OutMask"].As<GrayImage>();check(moved.Outputs["ProcessedPixels"].As<long>()==64&&mask[16,12]==255&&mask[8,8]==0,"位置信息订阅平移掩膜并改变实际输出");Put("SelectWay",1);inputs["OriginPoint"]=PortValue.Point(new(0,0));inputs["RunPoint"]=PortValue.Point(new(8,4));check(Run().Outputs["OutMask"].As<GrayImage>().Pixels.SequenceEqual(mask.Pixels),"按点订阅和按信息输入产生相同平移结果");Put("SelectWay",2);Put("RunPointBaseX",8d);Put("RunPointBaseY",4d);check(Run().Outputs["OutMask"].As<GrayImage>().Pixels.SequenceEqual(mask.Pixels),"按坐标参数参与实际位置修正");Put("RunScaleX",2d);check(Run().Outputs["ProcessedPixels"].As<long>()==128,"独立仿射掩膜执行非等比缩放");Put("RunScaleX",0d);check(Run().Status==ModuleStatus.Failed,"零缩放明确失败");
 var fixture=new FixtureValue(new(5,7,25,1.2,.8),new(12,16,-10,.7,1.5));var point=new Point2(10,9);var back=fixture.Transform(fixture.Transform(point),true);check(Math.Abs(back.X-point.X)<1e-9&&Math.Abs(back.Y-point.Y)<1e-9,"参考和运行姿态的仿射往返保持坐标");
 // Actual GraphExecutor, typed workflow inputs and subscriptions, rather than calling a host adapter only.
 Put("RunScaleX",1d);Put("SelectWay",0);Put("InheritWay",0);var registry=new ModuleRegistry();registry.Register(plugin.Descriptor,plugin.CreateRuntime);var args=new Dictionary<string,PortValue>{{"image",PortValue.Image(image)},{"region",PortValue.Region([rect])},{"fixture",PortValue.Fixture(new(new(),new(8,4)))}};var ports=new[]{new WorkflowInterfaceItem("i","image",DataKind.GrayImage),new WorkflowInterfaceItem("r","region",DataKind.Region),new WorkflowInterfaceItem("f","fixture",DataKind.Fixture)};var subscriptions=new[]{new WorkflowSubscription("b","Image",false,new(WorkflowSourceKind.WorkflowInput,"i")),new("b","Region",false,new(WorkflowSourceKind.WorkflowInput,"r")),new("b","CorrectInfo",false,new(WorkflowSourceKind.WorkflowInput,"f"))};var flow=new ProcedureDocument("main","main",[new("b",ImageBinaryPlugin.Id,"1.0.0","二值化",values)],[],[]){Configuration=new(){Inputs=ports,Subscriptions=subscriptions}};var result=new GraphExecutor(registry).RunAsync(flow,".",inputs:args).GetAwaiter().GetResult();check(result.Status==SessionStatus.Success&&result.Nodes.Single().Outputs["OutMask"].As<GrayImage>()[16,12]==255,"真实工作流输入经订阅驱动继承区域和Fixture算法");
 }
}
